const SOURCE_LABEL = 'IT Forum 2026 Praia Forte'
const TOP_OFFER = { pt: 'Pré-Vendas · Inteligência', en: 'Pre-Sales · Intelligence' }

export function getPraiaForteContacts(lang: Language = 'pt'): BenchmarkContact[] {
  return PRAIA_FORTE_RAW.map(c => ({
    source: 'itforum-praiaforte',
    sourceLabel: SOURCE_LABEL,
    name: c.name,
    role: c.role,
    company: c.company,
    sector: c.sector,
    city: c.city,
    revenue: c.revenue,
    opportunities: 0,
    topOffer: TOP_OFFER[lang],
    topScore: 0,
    tag: c.tag,
    briefingFiles: [{ label: c.briefingLabel, file: c.file }],
  }))
}
